CREATE TABLE filme (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(255) NOT NULL, duracao_minutos INTEGER NOT NULL);
CREATE TABLE sala (id BIGSERIAL PRIMARY KEY, nome VARCHAR(255) NOT NULL, capacidade INTEGER NOT NULL);
CREATE TABLE sessao (id BIGSERIAL PRIMARY KEY, filme_id BIGINT NOT NULL REFERENCES filme(id), sala_id BIGINT NOT NULL REFERENCES sala(id), inicio TIMESTAMP NOT NULL, preco_inteira NUMERIC(10,2) NOT NULL);
CREATE TABLE pedido (id BIGSERIAL PRIMARY KEY, data_hora TIMESTAMP NOT NULL, valor_total NUMERIC(10,2) NOT NULL);
CREATE TABLE ingresso (id BIGSERIAL PRIMARY KEY, sessao_id BIGINT NOT NULL REFERENCES sessao(id), pedido_id BIGINT NOT NULL REFERENCES pedido(id), tipo VARCHAR(20) NOT NULL, valor NUMERIC(10,2) NOT NULL);
